import{_ as l,a0 as o,w as n,s as p,ao as r,I as d,x as i,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"在 Linux 上簡單模擬系統負載的方法 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上簡單模擬系統負載的方法 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上簡單模擬系統負載的方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上簡單模擬系統負載的方法 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20170924 Simulate System Loads","title":"在 Linux 上簡單模擬系統負載的方法","tag":"201801","desc":""},"relativePath":"201801/20170924 Simulate System Loads.md","filePath":"[post].md"}'),h={name:"201801/20170924 Simulate System Loads.md"};function c(u,e,g,k,b,f){const s=o("Link");return n(),p("div",null,[e[13]||(e[13]=r(`<h1 id="在-linux-上簡單模擬系統負載的方法" tabindex="-1">在 Linux 上簡單模擬系統負載的方法 <a class="header-anchor" href="#在-linux-上簡單模擬系統負載的方法" aria-label="Permalink to “在 Linux 上簡單模擬系統負載的方法”">​</a></h1><p>系統管理員通常需要探索在不同負載對應用性能的影響。這意味着必須要重複地人為創造負載。當然，你可以通過專門的工具來實現，但有時你可能不想也無法安裝新工具。</p><p>每個 Linux 發行版中都自帶有創建負載的工具。他們不如專門的工具那麼靈活，但它們是現成的，而且無需專門學習。</p><h3 id="cpu" tabindex="-1">CPU <a class="header-anchor" href="#cpu" aria-label="Permalink to “CPU”">​</a></h3><p>下面命令會創建 CPU 負荷，方法是通過壓縮隨機數據並將結果發送到 <code>/dev/null</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat /dev/urandom | gzip -9 &gt; /dev/null</span></span></code></pre></div><p>如果你想要更大的負荷，或者系統有多個核，那麼只需要對數據進行壓縮和解壓就行了，像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat /dev/urandom | gzip -9 | gzip -d | gzip -9 | gzip -d &gt; /dev/null</span></span></code></pre></div><p>按下 <code>CTRL+C</code> 來終止進程。</p><h3 id="內存佔用" tabindex="-1">內存佔用 <a class="header-anchor" href="#內存佔用" aria-label="Permalink to “內存佔用”">​</a></h3><p>下面命令會減少可用內存的總量。它是通過在內存中創建文件系統然後往裏面寫文件來實現的。你可以使用任意多的內存，只需喲往裏面寫入更多的文件就行了。</p><p>首先，創建一個掛載點，然後將 ramfs 文件系統掛載上去：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir z</span></span>
<span class="line"><span>mount -t ramfs ramfs z/</span></span></code></pre></div><p>第二步，使用 <code>dd</code> 在該目錄下創建文件。這裏我們創建了一個 128M 的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dd if=/dev/zero of=z/file bs=1M count=128</span></span></code></pre></div><p>文件的大小可以通過下面這些操作符來修改：</p><ul><li><code>bs=</code> 塊大小。可以是任何數字後面接上 <code>B</code>（表示字節），<code>K</code>（表示 KB），<code>M</code>（ 表示 MB）或者 <code>G</code>（表示 GB）。</li><li><code>count=</code> 要寫多少個塊。</li></ul><h3 id="磁盤-i-o" tabindex="-1">磁盤 I/O <a class="header-anchor" href="#磁盤-i-o" aria-label="Permalink to “磁盤 I/O”">​</a></h3><p>創建磁盤 I/O 的方法是先創建一個文件，然後使用 <code>for</code> 循環來不停地拷貝它。</p><p>下面使用命令 <code>dd</code> 創建了一個全是零的 1G 大小的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dd if=/dev/zero of=loadfile bs=1M count=1024</span></span></code></pre></div><p>下面命令用 <code>for</code> 循環執行 10 次操作。每次都會拷貝 <code>loadfile</code> 來覆蓋 <code>loadfile1</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for i in {1..10}; do cp loadfile loadfile1; done</span></span></code></pre></div><p>通過修改 <code>{1..10}</code> 中的第二個參數來調整運行時間的長短。（LCTT 譯註：你的 Linux 系統中的默認使用的 <code>cp</code> 命令很可能是 <code>cp -i</code> 的別名，這種情況下覆寫會提示你輸入 <code>y</code> 來確認，你可以使用 <code>-f</code> 參數的 <code>cp</code> 命令來覆蓋此行為，或者直接用 <code>/bin/cp</code> 命令。）</p><p>若你想要一直運行，直到按下 <code>CTRL+C</code> 來停止，則運行下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>while true; do cp loadfile loadfile1; done</span></span></code></pre></div><hr>`,27)),d("p",null,[e[1]||(e[1]=i("via: ",-1)),a(s,{href:"https://bash-prompt.net/guides/create-system-load/"},{default:t(()=>[...e[0]||(e[0]=[i("https://bash-prompt.net/guides/create-system-load/",-1)])]),_:1})]),d("p",null,[e[5]||(e[5]=i("作者：",-1)),a(s,{href:"https://bash-prompt.net"},{default:t(()=>[...e[2]||(e[2]=[i("Elliot Cooper",-1)])]),_:1}),e[6]||(e[6]=i(" 譯者：",-1)),a(s,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[3]||(e[3]=[i("lujun9972",-1)])]),_:1}),e[7]||(e[7]=i(" 校對：",-1)),a(s,{href:"https://github.com/wxy"},{default:t(()=>[...e[4]||(e[4]=[i("wxy",-1)])]),_:1})]),d("p",null,[e[10]||(e[10]=i("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[8]||(e[8]=[i("LCTT",-1)])]),_:1}),e[11]||(e[11]=i(" 原創編譯，",-1)),a(s,{href:"https://linux.cn/"},{default:t(()=>[...e[9]||(e[9]=[i("Linux中國",-1)])]),_:1}),e[12]||(e[12]=i(" 榮譽推出",-1))])])}const y=l(h,[["render",c]]);export{x as __pageData,y as default};
